from pathlib import Path

home_path = Path('react-migration/src/pages/HomePage.jsx')
home_css_path = Path('react-migration/src/pages/HomePageDashboard.css')
wellness_path = Path('react-migration/src/pages/WellnessPage.jsx')

home = home_path.read_text()
wellness = wellness_path.read_text()
home_css = home_css_path.read_text()

# 1. Player check-in state on Home.
needle = "  const [playerTrainingSummary, setPlayerTrainingSummary] = useState({ weekLoads: [0, 0, 0, 0, 0], recentSessions: 0, recentRpeMean: null, historyCoverageDays: 0, ready: false, label: 'Conociendo tu ritmo', text: 'Estamos empezando a conocer tu ritmo habitual de entrenamiento.' });\n"
replacement = needle + """  const [checkinOpen, setCheckinOpen] = useState(false);\n  const [checkinFatigue, setCheckinFatigue] = useState(2);\n  const [checkinSleep, setCheckinSleep] = useState(3);\n  const [checkinPain, setCheckinPain] = useState(0);\n  const [checkinNotes, setCheckinNotes] = useState('');\n  const [checkinSaving, setCheckinSaving] = useState(false);\n  const [checkinError, setCheckinError] = useState('');\n"""
if needle not in home:
    raise SystemExit('Home state marker not found')
home = home.replace(needle, replacement, 1)

# 2. Make primary cards render as soon as the base dashboard query resolves for players.
needle = """        const pastTrainings = pastTrainingResult.data || [];\n\n        let nextPlayers = [];\n"""
replacement = """        const pastTrainings = pastTrainingResult.data || [];\n\n        // En jugadoras, no bloqueamos las tarjetas principales mientras termina de\n        // cargarse el resumen personal de las últimas semanas.\n        if (!isStaff && active) {\n          setNextTraining(training);\n          setNextMatch(match);\n          setRecentMatches(recentMatchResult.data || []);\n          setLoading(false);\n        }\n\n        let nextPlayers = [];\n"""
if needle not in home:
    raise SystemExit('Early render marker not found')
home = home.replace(needle, replacement, 1)

# 3. Add player daily wellness state and submit handler before render.
needle = """  const trainingPlan = nextTraining ? planLines(nextTraining) : [];\n\n  return (\n"""
replacement = """  const trainingPlan = nextTraining ? planLines(nextTraining) : [];\n  const localNow = new Date();\n  const todayKey = `${localNow.getFullYear()}-${String(localNow.getMonth() + 1).padStart(2, '0')}-${String(localNow.getDate()).padStart(2, '0')}`;\n  const playerWellnessToday = !isStaff ? wellness.find((row) => row.entry_date === todayKey) || null : null;\n\n  function openDailyCheckin() {\n    setCheckinFatigue(2);\n    setCheckinSleep(3);\n    setCheckinPain(0);\n    setCheckinNotes('');\n    setCheckinError('');\n    setCheckinOpen(true);\n  }\n\n  async function submitDailyCheckin(event) {\n    event.preventDefault();\n    if (!identity?.player?.id || playerWellnessToday || checkinSaving) return;\n    setCheckinSaving(true);\n    setCheckinError('');\n    try {\n      const { data, error: insertError } = await supabase\n        .from('wellness_entries')\n        .insert({\n          player_id: identity.player.id,\n          entry_date: todayKey,\n          general_state: checkinFatigue,\n          fatigue: checkinFatigue,\n          sleep: checkinSleep,\n          pain_score: checkinPain,\n          notes: checkinNotes.trim()\n        })\n        .select('player_id,entry_date,general_state,fatigue,sleep,pain_score,notes')\n        .single();\n      if (insertError) throw insertError;\n      setWellness((rows) => [data, ...rows.filter((row) => row.entry_date !== todayKey)]);\n      setCheckinOpen(false);\n    } catch (saveError) {\n      if (saveError?.code === '23505') {\n        setCheckinOpen(false);\n        setWellness((rows) => rows.some((row) => row.entry_date === todayKey) ? rows : [{ player_id: identity.player.id, entry_date: todayKey, fatigue: checkinFatigue, sleep: checkinSleep, pain_score: checkinPain, notes: checkinNotes.trim() }, ...rows]);\n      } else {\n        setCheckinError(saveError?.message || 'No se pudo guardar tu bienestar.');\n      }\n    } finally {\n      setCheckinSaving(false);\n    }\n  }\n\n  return (\n"""
if needle not in home:
    raise SystemExit('Home render marker not found')
home = home.replace(needle, replacement, 1)

# 4. Player-friendly section heading.
old = """      <header className=\"coach-home-section-head\">\n        <div>\n          <small>Panel técnico</small>\n          <h2>Lo importante, de un vistazo</h2>\n          <p>Entrenos, competición, bienestar y carga del equipo.</p>\n        </div>\n      </header>\n"""
new = """      <header className=\"coach-home-section-head\">\n        <div>\n          <small>{isStaff ? 'Panel técnico' : 'Tu equipo'}</small>\n          <h2>{isStaff ? 'Lo importante, de un vistazo' : 'Lo importante para ti'}</h2>\n          <p>{isStaff ? 'Entrenos, competición, bienestar y carga del equipo.' : 'Próximo entreno, partido y tu seguimiento personal.'}</p>\n        </div>\n      </header>\n"""
if old not in home:
    raise SystemExit('Home heading block not found')
home = home.replace(old, new, 1)

# 5. Daily wellness banner on Home.
needle = """      {error ? <div className=\"coach-home-error\">{error}</div> : null}\n\n      <div className=\"coach-home-grid\">\n"""
replacement = """      {error ? <div className=\"coach-home-error\">{error}</div> : null}\n\n      {!isStaff && !loading && !playerWellnessToday ? (\n        <button type=\"button\" className=\"player-daily-wellness-banner\" onClick={openDailyCheckin}>\n          <span className=\"player-daily-wellness-icon\"><HeartPulse /></span>\n          <span className=\"player-daily-wellness-copy\"><small>Bienestar diario</small><strong>Registrar bienestar de hoy</strong><span>Fatiga, sueño y molestias · menos de 1 minuto</span></span>\n          <ChevronRight />\n        </button>\n      ) : null}\n\n      <div className=\"coach-home-grid\">\n"""
if needle not in home:
    raise SystemExit('Banner insertion marker not found')
home = home.replace(needle, replacement, 1)

# 6. Player training card should not show team confirmation counts.
old = """            <div className=\"coach-mini-stats\">\n              <span>{attendanceModel.confirmed} confirmadas</span>\n              <span>{attendanceModel.pending} pendientes</span>\n              <span>{eventDuration(nextTraining)} min</span>\n            </div>\n"""
new = """            <div className={`coach-mini-stats ${isStaff ? '' : 'coach-mini-stats-player'}`}>\n              {isStaff ? (<>\n                <span>{attendanceModel.confirmed} confirmadas</span>\n                <span>{attendanceModel.pending} pendientes</span>\n              </>) : <span>Tu próxima sesión</span>}\n              <span>{eventDuration(nextTraining)} min</span>\n            </div>\n"""
if old not in home:
    raise SystemExit('Mini stats block not found')
home = home.replace(old, new, 1)

# 7. Coach-only cards: hide 7-day team wellness and phase form from players.
old = """        <article className=\"coach-card coach-wellness-card\">\n          <div className=\"coach-wellness-head\">\n            <div>\n              <span className=\"coach-card-kicker\"><HeartPulse size={13} /> Próximos 7 días</span>\n              <h3>Carga y bienestar</h3>\n            </div>\n            <HeartPulse size={22} color=\"#7b8798\" />\n          </div>\n          <div className=\"coach-wellness-grid\">\n            <div className=\"coach-wellness-metric low\"><strong>{wellnessModel.low}</strong><span>Fatiga baja</span></div>\n            <div className=\"coach-wellness-metric medium\"><strong>{wellnessModel.medium}</strong><span>Fatiga moderada</span></div>\n            <div className=\"coach-wellness-metric high\"><strong>{wellnessModel.high}</strong><span>Fatiga alta</span></div>\n          </div>\n          <div className=\"coach-wellness-foot\">\n            <span>{wellnessModel.values.length} respuestas recientes</span>\n            <Link to=\"/wellness\">Ver detalle <ChevronRight size={12} /></Link>\n          </div>\n        </article>\n\n        <article className=\"coach-card coach-form-card\">\n          <span className=\"coach-card-kicker\"><Sparkles size={13} /> En forma esta fase</span>\n          <h3>Últimos partidos</h3>\n          <div className=\"coach-form-line\" />\n          {completedMatches.length ? (\n            <p>{completedMatches.slice(0, 3).map((event) => event.payload?.result).filter(Boolean).join(' · ')}</p>\n          ) : (\n            <p>La temporada todavía no ha comenzado.</p>\n          )}\n        </article>\n"""
new = """        {isStaff ? (<>\n          <article className=\"coach-card coach-wellness-card\">\n            <div className=\"coach-wellness-head\">\n              <div>\n                <span className=\"coach-card-kicker\"><HeartPulse size={13} /> Próximos 7 días</span>\n                <h3>Carga y bienestar</h3>\n              </div>\n              <HeartPulse size={22} color=\"#7b8798\" />\n            </div>\n            <div className=\"coach-wellness-grid\">\n              <div className=\"coach-wellness-metric low\"><strong>{wellnessModel.low}</strong><span>Fatiga baja</span></div>\n              <div className=\"coach-wellness-metric medium\"><strong>{wellnessModel.medium}</strong><span>Fatiga moderada</span></div>\n              <div className=\"coach-wellness-metric high\"><strong>{wellnessModel.high}</strong><span>Fatiga alta</span></div>\n            </div>\n            <div className=\"coach-wellness-foot\">\n              <span>{wellnessModel.values.length} respuestas recientes</span>\n              <Link to=\"/wellness\">Ver detalle <ChevronRight size={12} /></Link>\n            </div>\n          </article>\n\n          <article className=\"coach-card coach-form-card\">\n            <span className=\"coach-card-kicker\"><Sparkles size={13} /> En forma esta fase</span>\n            <h3>Últimos partidos</h3>\n            <div className=\"coach-form-line\" />\n            {completedMatches.length ? (\n              <p>{completedMatches.slice(0, 3).map((event) => event.payload?.result).filter(Boolean).join(' · ')}</p>\n            ) : (\n              <p>La temporada todavía no ha comenzado.</p>\n            )}\n          </article>\n        </>) : null}\n"""
if old not in home:
    raise SystemExit('Coach-only card block not found')
home = home.replace(old, new, 1)

# 8. Home modal for the daily check-in.
needle = """      </div>\n      <div className=\"coach-mobile-spacer\" />\n"""
modal = """      </div>\n\n      {checkinOpen && !isStaff ? (\n        <div className=\"player-checkin-backdrop\" role=\"presentation\" onMouseDown={(event) => { if (event.target === event.currentTarget) setCheckinOpen(false); }}>\n          <form className=\"player-checkin-modal\" onSubmit={submitDailyCheckin}>\n            <div className=\"player-checkin-head\">\n              <div><small>Bienestar diario</small><h3>¿Cómo estás hoy?</h3><p>Responde pensando en cómo te encuentras ahora mismo.</p></div>\n              <button type=\"button\" className=\"player-checkin-close\" onClick={() => setCheckinOpen(false)} aria-label=\"Cerrar\">×</button>\n            </div>\n\n            <div className=\"player-checkin-field\"><div><strong>Fatiga</strong><span>1 = muy fresca · 5 = muy cansada</span></div><div className=\"player-checkin-scale\">{[1,2,3,4,5].map((value) => <button key={`f-${value}`} type=\"button\" className={checkinFatigue === value ? 'selected' : ''} onClick={() => setCheckinFatigue(value)}>{value}</button>)}</div></div>\n            <div className=\"player-checkin-field\"><div><strong>Sueño</strong><span>1 = muy mal · 5 = muy bien</span></div><div className=\"player-checkin-scale\">{[1,2,3,4,5].map((value) => <button key={`s-${value}`} type=\"button\" className={checkinSleep === value ? 'selected' : ''} onClick={() => setCheckinSleep(value)}>{value}</button>)}</div></div>\n            <div className=\"player-checkin-field\"><div><strong>Molestias</strong><span>0 = nada · 10 = dolor máximo</span></div><div className=\"player-checkin-pain\"><input type=\"range\" min=\"0\" max=\"10\" step=\"1\" value={checkinPain} onChange={(event) => setCheckinPain(Number(event.target.value))} /><strong>{checkinPain}/10</strong></div></div>\n            <label className=\"player-checkin-notes\"><span>¿Algo que quieras comentar? <small>Opcional</small></span><textarea rows=\"3\" value={checkinNotes} onChange={(event) => setCheckinNotes(event.target.value)} placeholder=\"Molestia concreta, poco descanso, sensaciones…\" /></label>\n            {checkinError ? <div className=\"player-checkin-error\">{checkinError}</div> : null}\n            <button className=\"player-checkin-submit\" type=\"submit\" disabled={checkinSaving}>{checkinSaving ? 'Guardando…' : 'Guardar bienestar'}</button>\n          </form>\n        </div>\n      ) : null}\n\n      <div className=\"coach-mobile-spacer\" />\n"""
if needle not in home:
    raise SystemExit('Home modal marker not found')
home = home.replace(needle, modal, 1)

# 9. Remove the daily form from Wellness player view; that screen becomes history/insight only.
old = """        <header className=\"wellness-page-head\">\n          <div>\n            <span className=\"wellness-eyebrow\"><HeartPulse size={14} /> Tu bienestar</span>\n            <h1>¿Cómo estás hoy?</h1>\n            <p>Tu información es personal y la utiliza el cuerpo técnico para adaptar mejor el entrenamiento.</p>\n          </div>\n        </header>\n\n        {error ? <div className=\"wellness-error\">{error}</div> : null}\n        {saveMessage ? <div className=\"wellness-save-message\">{saveMessage}</div> : null}\n\n        {currentPlayerToday ? (\n          <section className=\"wellness-player-complete\">\n            <div className=\"wellness-complete-icon\"><CheckCircle2 /></div>\n            <div>\n              <span>Registro de hoy completado</span>\n              <h2>Tu valoración ya está guardada</h2>\n              <p>No necesitas volver a responder hoy. Mañana se abrirá un nuevo check-in.</p>\n            </div>\n            <div className=\"wellness-complete-grid\">\n              <WellnessMetric label=\"Fatiga\" value={currentPlayerToday.fatigue} tone={fatigueTone(currentPlayerToday.fatigue)} suffix=\"/5\" />\n              <WellnessMetric label=\"Sueño\" value={currentPlayerToday.sleep} tone={sleepTone(currentPlayerToday.sleep)} suffix=\"/5\" />\n              <WellnessMetric label=\"Dolor\" value={currentPlayerToday.pain_score ?? 0} tone={painTone(currentPlayerToday.pain_score ?? 0)} suffix=\"/10\" />\n            </div>\n          </section>\n        ) : (\n          <WellnessForm\n            title={`Hola${player ? `, ${playerName(player).split(/\\s+/)[0]}` : ''}`}\n            subtitle=\"Responde una vez al día. Te llevará menos de un minuto.\"\n            fatigue={fatigue}\n            setFatigue={setFatigue}\n            sleep={sleep}\n            setSleep={setSleep}\n            pain={pain}\n            setPain={setPain}\n            notes={notes}\n            setNotes={setNotes}\n            saving={saving}\n            onSubmit={submitPlayerWellness}\n          />\n        )}\n\n"""
new = """        <header className=\"wellness-page-head\">\n          <div>\n            <span className=\"wellness-eyebrow\"><HeartPulse size={14} /> Tu bienestar</span>\n            <h1>Cómo te has encontrado</h1>\n            <p>Aquí puedes revisar tus sensaciones recientes y cómo han ido cambiando.</p>\n          </div>\n        </header>\n\n        {error ? <div className=\"wellness-error\">{error}</div> : null}\n        {!currentPlayerToday ? <div className=\"wellness-inline-empty\">Tu registro de hoy está pendiente. Puedes completarlo desde el banner de Inicio.</div> : null}\n\n"""
if old not in wellness:
    raise SystemExit('Wellness player form block not found')
wellness = wellness.replace(old, new, 1)

# 10. Styles for the player-only banner and check-in modal.
css_add = r'''

/* Bienestar diario de jugadora: banner en Inicio + modal, sin bloquear el dashboard */
.player-daily-wellness-banner{width:100%;min-height:76px;padding:13px 15px;border:1px solid #e5b342;border-radius:18px;background:linear-gradient(105deg,#ffc42d 0%,#f09a0a 100%);box-shadow:0 10px 24px rgba(216,139,7,.16);display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:11px;text-align:left;color:#2d2208;cursor:pointer}.player-daily-wellness-icon{width:42px;height:42px;border-radius:14px;background:rgba(255,255,255,.58);display:grid;place-items:center}.player-daily-wellness-icon svg{width:23px}.player-daily-wellness-copy{min-width:0}.player-daily-wellness-copy small{display:block;font-size:.57rem;font-weight:900;text-transform:uppercase;letter-spacing:.075em;color:#7b5400}.player-daily-wellness-copy strong{display:block;margin-top:2px;font-size:.91rem;line-height:1.1}.player-daily-wellness-copy>span{display:block;margin-top:3px;font-size:.61rem;color:#6d520e}.player-daily-wellness-banner>svg{width:18px}.coach-mini-stats-player{grid-template-columns:1fr 1fr}.player-checkin-backdrop{position:fixed;inset:0;z-index:1200;padding:18px;background:rgba(15,23,42,.5);backdrop-filter:blur(4px);display:flex;align-items:flex-end;justify-content:center}.player-checkin-modal{width:min(100%,520px);max-height:calc(100dvh - 36px);overflow:auto;padding:18px;border:1px solid #e6e9ee;border-radius:24px;background:#fff;box-shadow:0 24px 70px rgba(15,23,42,.28)}.player-checkin-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding-bottom:14px;border-bottom:1px solid #eef1f4}.player-checkin-head small{color:#ad6a09;font-size:.58rem;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.player-checkin-head h3{margin:3px 0 3px;color:#1e293b;font-size:1.3rem}.player-checkin-head p{margin:0;color:#8792a1;font-size:.68rem;line-height:1.4}.player-checkin-close{width:38px;height:38px;flex:0 0 38px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;color:#6b7280;font-size:1.45rem;line-height:1}.player-checkin-field{padding:14px 0;border-bottom:1px solid #eef1f4}.player-checkin-field>div:first-child{display:flex;justify-content:space-between;gap:10px;align-items:baseline}.player-checkin-field strong{color:#263247;font-size:.76rem}.player-checkin-field span{color:#8b95a3;font-size:.58rem}.player-checkin-scale{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin-top:10px}.player-checkin-scale button{height:42px;border:1px solid #e0e5ea;border-radius:12px;background:#f8fafc;color:#596579;font-weight:900}.player-checkin-scale button.selected{border-color:#e6a321;background:#fff5d9;color:#9a5d05;box-shadow:inset 0 0 0 1px #e6a321}.player-checkin-pain{display:grid!important;grid-template-columns:minmax(0,1fr) auto;align-items:center!important;gap:12px!important;margin-top:10px}.player-checkin-pain input{width:100%;accent-color:#e79d12}.player-checkin-pain strong{min-width:44px;text-align:right;font-size:.82rem}.player-checkin-notes{display:block;padding-top:14px}.player-checkin-notes>span{display:block;color:#354155;font-size:.68rem;font-weight:850}.player-checkin-notes small{color:#9aa3af;font-weight:600}.player-checkin-notes textarea{width:100%;margin-top:7px;padding:11px;border:1px solid #dfe4ea;border-radius:12px;background:#fbfcfd;color:#283548;font:inherit;font-size:.7rem;resize:vertical}.player-checkin-error{margin-top:10px;padding:9px 10px;border-radius:10px;background:#fff1f2;color:#b42318;font-size:.65rem}.player-checkin-submit{width:100%;min-height:44px;margin-top:14px;border:0;border-radius:12px;background:linear-gradient(90deg,#f5b820,#ee930a);color:#302208;font-weight:900;font-size:.72rem}.player-checkin-submit:disabled{opacity:.65}.player-week-card{grid-column:1/-1}
@media(max-width:560px){.player-daily-wellness-banner{border-radius:16px;padding:12px}.player-daily-wellness-icon{width:38px;height:38px}.player-checkin-backdrop{padding:0;align-items:flex-end}.player-checkin-modal{max-height:92dvh;border-radius:24px 24px 0 0;padding:17px 16px 20px}.player-checkin-scale button{height:40px}.player-week-card{grid-column:auto}}
'''
if 'Bienestar diario de jugadora: banner en Inicio + modal' not in home_css:
    home_css += css_add

home_path.write_text(home)
wellness_path.write_text(wellness)
